import type { CardRow } from './cards-api';
import { fetchVocab, type WordMap } from './stats-api';
import { apiFetch } from './supabase';

// Leech rescue: a card failed (rated 다시) LEECH_LAPSES times or more usually
// fails because the sentence is too hard, not the word. Offer easier
// sentences for the same word, from what exists without storing anything new:
//
//  - the card's own sentence cut down to the clause holding the word;
//  - other cards the reader mined for the same word;
//  - WordNet's usage examples (examples.json, generated by
//    ../extension/scripts/extract-examples.mjs; ~1.7 MB, fetched only when
//    the reader asks for alternatives).
//
// The extension's one-unknown sentence picks (made when a card is saved) would
// be the best source, but they aren't kept with the card -- that would need a
// new column, and a card push carrying an unknown column fails outright until
// the SQL is run. Candidates are ordered by how many words in them the reader
// hasn't marked 알아요 (a rough word check against the synced vocabulary, not
// real lemmatizing -- the review page doesn't load the tokenizer), then length.

export const LEECH_LAPSES = 4;

export interface Alternative {
  sentence: string;
  targetStart: number;
  surface: string;
  source: '짧게 줄인 문장' | '내가 저장한 다른 문장' | '사전 예문';
}

let examples: Promise<Record<string, [string, number, string][]>> | null = null;
let vocab: Promise<WordMap | null> | null = null;

/** The clause around the target, if it's clearly shorter than the whole sentence. */
function shorterClause(c: CardRow): Alternative | null {
  const s = c.sentence;
  const at = c.target_start;
  const cuts = [...s.matchAll(/[,;:—–]\s+|\s+[-–]\s+/g)].map((m) => ({ from: m.index!, to: m.index! + m[0].length }));
  let start = 0;
  let end = s.length;
  for (const cut of cuts) {
    if (cut.to <= at) start = cut.to;
    else if (cut.from >= at + c.surface.length) { end = cut.from; break; }
  }
  const raw = s.slice(start, end);
  const from = start + (raw.length - raw.trimStart().length);
  let clause = raw.trim();
  if (clause.split(/\s+/).length < 3 || clause.length > s.length * 0.75) return null;
  const targetStart = at - from;
  // Capitalize the first letter unless that's the target itself (its surface must still match).
  if (targetStart > 0) clause = clause[0].toUpperCase() + clause.slice(1);
  if (!/[.!?]$/.test(clause)) clause += '.';
  return { sentence: clause, targetStart, surface: c.surface, source: '짧게 줄인 문장' };
}

/** Words in `text` the reader hasn't marked known (crude: lowercase word, or minus a common ending). */
function unknownCount(text: string, skip: string, words: WordMap | null): number {
  if (!words) return 0;
  let n = 0;
  for (const w of text.toLowerCase().match(/[a-z']+/g) ?? []) {
    if (skip.toLowerCase().split(/\s+/).includes(w)) continue;
    const forms = [w, w.replace(/(ies)$/, 'y'), w.replace(/(es|s|ed|ing|ly)$/, ''), w.replace(/(d)$/, '')];
    if (!forms.some((f) => words[f] === 'known')) n++;
  }
  return n;
}

export async function leechAlternatives(c: CardRow): Promise<Alternative[]> {
  examples ??= fetch('/examples.json').then((r) => r.json()).catch(() => ({}));
  vocab ??= fetchVocab().catch(() => null);
  const others = apiFetch(
    `/rest/v1/cards?lemma=eq.${encodeURIComponent(c.lemma)}&id=neq.${c.id}&select=sentence,surface,target_start&limit=10`,
  ).then((r) => (r.ok ? (r.json() as Promise<Pick<CardRow, 'sentence' | 'surface' | 'target_start'>[]>) : [])).catch(() => []);

  const [ex, words, mine] = await Promise.all([examples, vocab, others]);
  const out: Alternative[] = [];
  const clause = shorterClause(c);
  if (clause && clause.targetStart >= 0) out.push(clause);
  for (const o of mine) out.push({ sentence: o.sentence, targetStart: o.target_start, surface: o.surface, source: '내가 저장한 다른 문장' });
  for (const [sentence, targetStart, surface] of ex[c.lemma] ?? []) out.push({ sentence, targetStart, surface, source: '사전 예문' });

  // Same word form only (case aside): the card keeps its `surface`, which the
  // extension's sync doesn't carry back, so "gave up" can't replace "giving up".
  const same = (a: Alternative) => a.surface.toLowerCase() === c.surface.toLowerCase();
  const seen = new Set([c.sentence]);
  return out
    .filter((a) => same(a) && !seen.has(a.sentence) && seen.add(a.sentence) && a.sentence.slice(a.targetStart, a.targetStart + a.surface.length) === a.surface)
    .map((a) => ({ a, unknown: unknownCount(a.sentence, a.surface, words) }))
    .sort((x, y) => x.unknown - y.unknown || x.a.sentence.length - y.a.sentence.length)
    .slice(0, 4)
    .map(({ a }) => a);
}
